  const token = useCallback(
    (name: string): string => tokens[name] ?? '',
    [tokens],
  );
  const name = theme?.name ?? 'default';

  return useMemo(
    () => ({name, mode: effectiveMode, token, tokens}),
    [name, effectiveMode, token, tokens],
  );
}

