export function isIosWebKit(
  view:
    | {CSS?: Partial<Pick<typeof CSS, 'supports'>>}
    | null
    | undefined = globalThis,
): boolean {
  return view?.CSS?.supports?.(IOS_SUPPORTS_QUERY) === true;
}

